    aboutTagline: 'તમારા વીડિયો, તમારી રીતે.',
    aboutMissionTitle: 'અમારું મિશન',
    aboutMissionP1: 'ClipVora એ એક ઝડપી, મફત અને વિશ્વસનીય ઓનલાઈન વીડિયો ડાઉનલોડર છે જે વપરાશકર્તાઓને ઈન્ટરનેટ પરથી તેમની મનપસંદ સામગ્રી સરળતાથી સાચવવામાં મદદ કરે છે. માત્ર થોડા ક્લિકમાં, તમે YouTube, TikTok, Instagram, Facebook, અને X જેવા લોકપ્રિય પ્લેટફોર્મ પરથી સામગ્રી ડાઉનલોડ કરી શકો છો.',
    aboutMissionP2: 'અમે દરેક માટે વીડિયો અને સંગીત સાચવવાને સરળ, સુરક્ષિત અને સુલભ બનાવવા માટે અહીં છીએ. તેથી જ અમે એક એવું પ્લેટફોર્મ બનાવ્યું છે જે તમામ ઉપકરણો અને બ્રાઉઝર્સ પર કામ કરે છે, જેથી તમે ગમે ત્યારે, ગમે ત્યાં ઉચ્ચ ગુણવત્તામાં વીડિયો અને સંગીત ડાઉનલોડ કરી શકો.',
