    aboutVal1Title: 'ઝડપી અને મફત',
    aboutVal1Desc: 'શૂન્ય ખર્ચે વીજળી-ઝડપી ડાઉનલોડ. કોઈ છુપા ચાર્જ નહીં, કોઈ પ્રીમિયમ ટિયર નહીં — માત્ર શુદ્ધ પ્રદર્શન.',
    aboutVal2Title: 'સુરક્ષિત અને ખાનગી',
    aboutVal2Desc: 'તમારી ગોપનીયતા મહત્વની છે. અમે એક જાહેરાત-મુક્ત પ્લેટફોર્મ જાળવીએ છીએ જે તમારા ડેટા અને બ્રાઉઝિંગ આદતોનું સન્માન કરે છે.',
    aboutVal3Title: 'મલ્ટી-પ્લેટફોર્મ',
    aboutVal3Desc: 'YouTube, TikTok, Instagram, Facebook, X અને અન્ય ઘણા પ્લેટફોર્મ પર સરળતાથી કામ કરે છે.',
    aboutVal4Title: 'કોઈપણ ઉપકરણ',
    aboutVal4Desc: 'તમામ ઉપકરણો અને બ્રાઉઝર્સ પર કામ કરે છે. ડેસ્કટોપ, ટેબલેટ અથવા મોબાઈલ પર ડાઉનલોડ કરો — ગમે ત્યાં, ગમે ત્યારે.',
