    aboutVal6Desc: 'તમારા મનપસંદ સોશિયલ મીડિયા પ્લેટફોર્મની નવીનતમ સુવિધાઓને સમર્થન આપવા માટે સતત અપડેટ થાય છે.',
    aboutCommitTitle: 'અમારી પ્રતિબદ્ધતા',
    aboutCommitDesc: 'અમે ગોપનીયતાનું સન્માન કરતું સુરક્ષિત, જાહેરાત-મુક્ત પ્લેટફોર્મ જાળવવા માટે પ્રતિબદ્ધ છીએ. ClipVora તમારી મનપસંદ સોશિયલ મીડિયા સાઈટ્સની નવીનતમ સુવિધાઓને સમર્થન આપવા અને તમામ ઉપકરણો અને બ્રાઉઝર્સ પર સુસંગતતા સુનિશ્ચિત કરવા માટે સતત અપડેટ થાય છે.',
