    aboutBadge: 'ഞങ്ങളെക്കുറിച്ച്',
    aboutTitle: 'ഞങ്ങളാണ്',
    aboutTagline: 'നിങ്ങളുടെ വീഡിയോകള്‍, നിങ്ങളുടെ രീതിയില്‍.',
    aboutMissionTitle: 'ഞങ്ങളുടെ ദൗത്യം',
    aboutMissionP1: 'ClipVora ഒരു വേഗതയേറിയ, സൗജന്യ, വിശ്വസനീയ ഓണ്‍ലൈന്‍ വീഡിയോ ഡൗണ്‍ലോഡറാണ്, ഇന്റര്‍നെറ്റില്‍ നിന്ന് ഇഷ്ടപ്പെട്ട ഉള്ളടക്കം എളുപ്പത്തില്‍ സേവ് ചെയ്യാന്‍ ഉപയോക്താക്കളെ സഹായിക്കുന്നു. കുറച്ച് ക്ലിക്കുകള്‍ കൊണ്ട് YouTube, TikTok, Instagram, Facebook, X പോലുള്ള പ്ലാറ്റ്‌ഫോമുകളില്‍ നിന്ന് ഉള്ളടക്കം ഡൗണ്‍ലോഡ് ചെയ്യാം.',
    aboutMissionP2: 'വീഡിയോയും സംഗീതവും സേവ് ചെയ്യല്‍ എല്ലാവര്‍ക്കും എളുപ്പവും സുരക്ഷിതവും പ്രാപ്യവുമാക്കാന്‍ ഞങ്ങള്‍ ഇവിടെയുണ്ട്. അതുകൊണ്ടാണ് എല്ലാ ഉപകരണങ്ങളിലും ബ്രൗസറുകളിലും പ്രവര്‍ത്തിക്കുന്ന ഒരു പ്ലാറ്റ്‌ഫോം ഞങ്ങള്‍ നിര്‍മ്മിച്ചത്.',
    aboutWhyTitle: 'ClipVora എന്തുകൊണ്ട് തിരഞ്ഞെടുക്കണം?',
    aboutWhySubtitle: 'ഉപയോക്താവിനെ മനസ്സില്‍ വെച്ചുകൊണ്ട് നിര്‍മ്മിച്ചത്, ഓരോ ഘട്ടത്തിലും.',
    aboutVal1Title: 'വേഗതയേറിയതും സൗജന്യവും',
    aboutVal1Desc: 'പൂജ്യം ചെലവില്‍ മിന്നല്‍ വേഗത്തിലുള്ള ഡൗണ്‍ലോഡുകള്‍. മറഞ്ഞിരിക്കുന്ന ചാര്‍ജുകളില്ല — ശുദ്ധമായ പ്രകടനം മാത്രം.',
    aboutVal2Title: 'സുരക്ഷിതവും സ്വകാര്യവും',
    aboutVal2Desc: 'നിങ്ങളുടെ സ്വകാര്യത പ്രധാനമാണ്. നിങ്ങളുടെ ഡാറ്റയെ ബഹുമാനിക്കുന്ന പരസ്യ-ലഘു പ്ലാറ്റ്‌ഫോം ഞങ്ങള്‍ പരിപാലിക്കുന്നു.',
    aboutVal3Title: 'മള്‍ട്ടി-പ്ലാറ്റ്‌ഫോം',
    aboutVal3Desc: 'YouTube, TikTok, Instagram, Facebook, X എന്നിവയിലും മറ്റ് പല പ്ലാറ്റ്‌ഫോമുകളിലും തടസ്സമില്ലാതെ പ്രവര്‍ത്തിക്കുന്നു.',
    aboutVal4Title: 'ഏത് ഉപകരണവും',
    aboutVal4Desc: 'എല്ലാ ഉപകരണങ്ങളിലും ബ്രൗസറുകളിലും പ്രവര്‍ത്തിക്കുന്നു. ഡെസ്ക്ടോപ്പ്, ടാബ്‌ലെറ്റ്, മൊബൈല്‍ — എവിടെയും, എപ്പോഴും.',
    aboutVal5Title: 'ഒന്നിലധികം ഫോര്‍മാറ്റുകള്‍',
    aboutVal5Desc: 'നിങ്ങള്‍ക്ക് ആവശ്യമുള്ളത് കൃത്യമായി സേവ് ചെയ്യാന്‍ വിശാലമായ ഫോര്‍മാറ്റുകളും റെസലൂഷനുകളും പിന്തുണയ്ക്കുന്നു.',
    aboutVal6Title: 'എല്ലായ്‌പ്പോഴും അപ്‌ഡേറ്റ്',
    aboutVal6Desc: 'നിങ്ങളുടെ പ്രിയപ്പെട്ട സോഷ്യല്‍ മീഡിയ പ്ലാറ്റ്‌ഫോമുകളുടെ ഏറ്റവും പുതിയ ഫീച്ചറുകള്‍ പിന്തുണയ്ക്കാന്‍ തുടര്‍ച്ചയായി അപ്‌ഡേറ്റ് ചെയ്യുന്നു.',
    aboutCommitTitle: 'ഞങ്ങളുടെ പ്രതിബദ്ധത',
    aboutCommitDesc: 'സ്വകാര്യതയെ ബഹുമാനിക്കുന്ന സുരക്ഷിതമായ, പരസ്യ-ലഘു പ്ലാറ്റ്‌ഫോം പരിപാലിക്കാന്‍ ഞങ്ങള്‍ പ്രതിജ്ഞാബദ്ധരാണ്. ClipVora നിങ്ങളുടെ പ്രിയപ്പെട്ട സോഷ്യല്‍ മീഡിയ സൈറ്റുകളുടെ ഏറ്റവും പുതിയ ഫീച്ചറുകള്‍ പിന്തുണയ്ക്കാനും എല്ലാ ഉപകരണങ്ങളിലും ബ്രൗസറുകളിലും അനുയോജ്യത ഉറപ്പാക്കാനും തുടര്‍ച്ചയായി അപ്‌ഡേറ്റ് ചെയ്യുന്നു.',
    aboutPromise1: 'രജിസ്ട്രേഷന്‍ ആവശ്യമില്ല',
    aboutPromise2: 'മറഞ്ഞിരിക്കുന്ന ഫീസോ ചാര്‍ജുകളോ ഇല്ല',
    aboutPromise3: 'സ്വകാര്യതയെ ബഹുമാനിക്കുന്ന പ്ലാറ്റ്‌ഫോം',
