    // About page
    aboutBadge: 'మా గురించి',
    aboutTitle: 'మేము',
    aboutTagline: 'మీ వీడియోలు, మీ విధంగా.',
    aboutMissionTitle: 'మా లక్ష్యం',
    aboutMissionP1: 'ClipVora అనేది వేగవంతమైన, ఉచిత మరియు నమ్మకమైన ఆన్‌లైన్ వీడియో డౌన్‌లోడర్, ఇది ఇంటర్నెట్ నుండి వారి అభిమాన కంటెంట్‌ను సులభంగా సేవ్ చేయడంలో వినియోగదారులకు సహాయపడుతుంది. కొన్ని క్లిక్‌లతో, మీరు YouTube, TikTok, Instagram, Facebook మరియు X వంటి ప్రముఖ ప్లాట్‌ఫారమ్‌ల నుండి కంటెంట్‌ను సులభంగా డౌన్‌లోడ్ చేయవచ్చు.',
    aboutMissionP2: 'వీడియో మరియు మ్యూజిక్ సేవింగ్‌ను అందరికీ సులభంగా, సురక్షితంగా మరియు అందుబాటులో ఉంచడానికి మేము ఇక్కడ ఉన్నాము. అందుకే అన్ని పరికరాలు మరియు బ్రౌజర్‌లలో పనిచేసే ప్లాట్‌ఫారమ్‌ను మేము నిర్మించాము.',
    aboutWhyTitle: 'ClipVora ఎందుకు ఎంచుకోవాలి?',
    aboutWhySubtitle: 'వినియోగదారుని దృష్టిలో ఉంచుకొని నిర్మించబడింది, ప్రతి అడుగులో.',
