    aboutVal1Desc: 'సున్నా ఖర్చుతో మెరుపు వేగంతో డౌన్‌లోడ్‌లు. దాచిన ఛార్జీలు లేవు, ప్రీమియం టైర్‌లు లేవు — కేవలం స్వచ్ఛమైన పనితీరు.',
    aboutVal2Title: 'సురక్షితం & ప్రైవేట్',
    aboutVal2Desc: 'మీ గోప్యత ముఖ్యం. మీ డేటా మరియు బ్రౌజింగ్ అలవాట్లను గౌరవించే యాడ్-లైట్ ప్లాట్‌ఫారమ్‌ను మేము నిర్వహిస్తాము.',
