    aboutVal6Title: 'ఎల్లప్పుడూ అప్‌డేట్',
    aboutVal6Desc: 'మీ అభిమాన సోషల్ మీడియా ప్లాట్‌ఫారమ్‌ల తాజా ఫీచర్‌లకు మద్దతు ఇవ్వడానికి నిరంతరం అప్‌డేట్ చేయబడుతుంది.',
    aboutCommitTitle: 'మా నిబద్ధత',
    aboutCommitDesc: 'గోప్యతను గౌరవించే సురక్షితమైన, యాడ్-లైట్ ప్లాట్‌ఫారమ్‌ను నిర్వహించడానికి మేము కట్టుబడి ఉన్నాము. ClipVora మీ అభిమాన సోషల్ మీడియా సైట్‌ల తాజా ఫీచర్‌లకు మద్దతు ఇవ్వడానికి మరియు అన్ని పరికరాలు మరియు బ్రౌజర్‌లలో అనుకూలతను నిర్ధారించడానికి నిరంతరం అప్‌డేట్ చేయబడుతుంది.',
