    // About page
    aboutBadge: 'எங்களைப் பற்றி',
    aboutTitle: 'நாங்கள்',
    aboutTagline: 'உங்கள் வீடியோக்கள், உங்கள் வழியில்.',
    aboutMissionTitle: 'எங்கள் நோக்கம்',
    aboutMissionP1: 'ClipVora என்பது இணையத்தில் இருந்து பிடித்த உள்ளடக்கத்தை எளிதாகச் சேமிக்க பயனர்களுக்கு உதவ வடிவமைக்கப்பட்ட வேகமான, இலவச மற்றும் நம்பகமான ஆன்லைன் வீடியோ பதிவிறக்கி ஆகும். சில கிளிக்குகளில், YouTube, TikTok, Instagram, Facebook மற்றும் X போன்ற பிரபலமான தளங்களிலிருந்து உள்ளடக்கத்தைப் பதிவிறக்கலாம்.',
    aboutMissionP2: 'வீடியோ மற்றும் இசையைச் சேமிப்பதை அனைவருக்கும் எளிதாகவும், பாதுகாப்பாகவும், அணுகக்கூடியதாகவும் மாற்ற நாங்கள் இங்கே இருக்கிறோம். எல்லா சாதனங்களிலும் உலாவிகளிலும் செயல்படும் ஒரு தளத்தை நாங்கள் உருவாக்கியுள்ளோம்.',
    aboutWhyTitle: 'ClipVora ஏன் தேர்வு செய்ய வேண்டும்?',
    aboutWhySubtitle: 'ஒவ்வொரு அடியிலும் பயனரை மனதில் வைத்து உருவாக்கப்பட்டது.',
    aboutVal1Title: 'வேகமான & இலவசம்',
    aboutVal1Desc: 'பூஜ்ஜிய செலவில் மின்னல் வேக பதிவிறக்கங்கள். மறைந்த கட்டணங்கள் இல்லை, பிரீமியம் நிலைகள் இல்லை — தூய செயல்திறன் மட்டுமே.',
    aboutVal2Title: 'பாதுகாப்பான & தனிப்பட்ட',
    aboutVal2Desc: 'உங்கள் தனியுரிமை முக்கியம். உங்கள் தரவு மற்றும் உலாவல் பழக்கங்களை மதிக்கும் விளம்பர-குறைவான தளத்தை நாங்கள் பராமரிக்கிறோம்.',
    aboutVal3Title: 'பல தளங்கள்',
    aboutVal3Desc: 'YouTube, TikTok, Instagram, Facebook, X மற்றும் பல தளங்களில் தடையின்றி செயல்படுகிறது.',
    aboutVal4Title: 'எந்த சாதனமும்',
    aboutVal4Desc: 'அனைத்து சாதனங்களிலும் உலாவிகளிலும் செயல்படுகிறது. டெஸ்க்டாப், டேப்லெட் அல்லது மொபைலில் பதிவிறக்கம் செய்யுங்கள் — எங்கும், எப்போதும்.',
    aboutVal5Title: 'பல வடிவங்கள்',
    aboutVal5Desc: 'உங்களுக்குத் தேவையானதைச் சரியாகச் சேமிக்க பரந்த அளவிலான வடிவங்கள் மற்றும் தெளிவுத்திறன்களை ஆதரிக்கிறது.',
    aboutVal6Title: 'எப்போதும் புதுப்பிக்கப்பட்டது',
    aboutVal6Desc: 'உங்கள் விருப்பமான சமூக ஊடக தளங்களின் சமீபத்திய அம்சங்களை ஆதரிக்க தொடர்ந்து புதுப்பிக்கப்படுகிறது.',
    aboutCommitTitle: 'எங்கள் உறுதிமொழி',
    aboutCommitDesc: 'தனியுரிமையை மதிக்கும் பாதுகாப்பான, விளம்பர-குறைவான தளத்தை பராமரிக்க நாங்கள் உறுதிபூண்டுள்ளோம். ClipVora உங்கள் விருப்பமான சமூக ஊடக தளங்களின் சமீபத்திய அம்சங்களை ஆதரிக்கவும் அனைத்து சாதனங்களிலும் உலாவிகளிலும் இணக்கத்தன்மையை உறுதிசெய்யவும் தொடர்ந்து புதுப்பிக்கப்படுகிறது.',
    aboutPromise1: 'பதிவு தேவையில்லை',
    aboutPromise2: 'மறைந்த கட்டணங்கள் இல்லை',
    aboutPromise3: 'தனியுரிமையை மதிக்கும் தளம்',
    aboutPromise4: 'வழக்கமான புதுப்பிப்புகள் & மேம்பாடுகள்',
    aboutPromise5: 'அனைத்து சாதனங்களிலும் உலாவிகளிலும் செயல்படுகிறது',
