    aboutMissionTitle: 'आमचे ध्येय',
    aboutMissionP1: 'ClipVora हे एक जलद, मोफत आणि विश्वासार्ह ऑनलाइन व्हिडिओ डाउनलोडर आहे जे वापरकर्त्यांना इंटरनेटवरून त्यांचा आवडता मजकूर सहजपणे जतन करण्यात मदत करते. फक्त काही क्लिक्समध्ये, तुम्ही YouTube, TikTok, Instagram, Facebook आणि X सारख्या लोकप्रिय प्लॅटफॉर्मवरून मजकूर डाउनलोड करू शकता.',
