    aboutMissionTitle: 'আমাদের মিশন',
    aboutMissionP1: 'ClipVora একটি দ্রুত, বিনামূল্যে এবং নির্ভরযোগ্য অনলাইন ভিডিও ডাউনলোডার যা ব্যবহারকারীদের ইন্টারনেট থেকে তাদের প্রিয় কন্টেন্ট সহজে সংরক্ষণ করতে সাহায্য করে। মাত্র কয়েকটি ক্লিকে, আপনি YouTube, TikTok, Instagram, Facebook এবং X এর মতো জনপ্রিয় প্ল্যাটফর্ম থেকে কন্টেন্ট ডাউনলোড করতে পারেন।',
